import unittest
from textkit.slug import slugify

class TestSlugify(unittest.TestCase):
    def test_slugify_with_leading_and_trailing_dashes(self):
        self.assertEqual(slugify('- Café con Leche!! -'), 'cafe-con-leche')

if __name__ == '__main__':
    unittest.main()
